import{t as e}from"./utils-COoNfFoj.js";var t={slug:`mike-and-matty`,influencerName:`Mike and Matty`,influencerHandle:`@mikeandmatty`,influencerAvatarUrl:`${e}/mike-and-matty-avatar.jpg`,heroDescription:`I’ve always loved using mental models to communicate ideas visually. But unless you’ve spent months learning how to use tools like After Effects, or you hired an animator, it was impossible to do. So, I used Computer to build a simple and repeatable way to create beautiful motion graphics, no skill required.`,assetTitle:`Mental Modeler`,screenshotUrl:`${e}/mike-and-matty.png`,remixUrl:`https://www.perplexity.ai/computer/a/1efb40c9-a9c3-4341-9855-8adee05f3052`,promptTitle:`Try Mike and Matty's Prompt`,promptText:`Build a single-page web tool where users design a short looping motion graphic by picking a shape (Venn, slider, spectrum, graph, matrix, flywheel, steps), setting background and line colors via paired pickers + hex inputs, optionally uploading a logo to extract a 6-color brand palette client-side (canvas + k-means), and exporting as WebM or MP4. Layout: live canvas preview on the left, a clean side panel of sectioned chip-based controls on the right, polished footer. Fully client-side, no API calls, with intentional design over generic AI styling.`};export{t as default};
